// Read-only replay of sealed evidence. All generated files go to new OS-temp directories.
import fs from 'node:fs';import os from 'node:os';import path from 'node:path';import crypto from 'node:crypto';import cp from 'node:child_process';import {pathToFileURL} from 'node:url';
const root=path.dirname(new URL(import.meta.url).pathname.replace(/^\/([A-Za-z]:)/,'$1'));const sdk=process.argv[2]||'D:/Projects/Unone/artifacts/spatial-hardening-sdk-v2';const analyzer=process.argv[3]||'D:/Projects/Unone/.toolcache/luau-0.734/luau-analyze.exe';const manifest=JSON.parse(fs.readFileSync(path.join(sdk,'sdk.json'),'utf8'));const binary=path.join(sdk,manifest.cli);const hash=crypto.createHash('sha256').update(fs.readFileSync(binary)).digest('hex');if(hash!=='d59c051d00ad47616978b6c4352a67092555baecfb090fb6b3442ca929c3e028')throw Error('Replay requires recorded SDK binary identity');
const temp=fs.mkdtempSync(path.join(os.tmpdir(),'scout-diagnostics-replay-'));for(const name of ['project.unone.json','scripts/main.luau','scenes/main.scene.json']){const dest=path.join(temp,name);fs.mkdirSync(path.dirname(dest),{recursive:true});fs.copyFileSync(path.join(root,'final-project',name),dest);}
let seq=0;function run(name,exe,args){const started=performance.now();const r=cp.spawnSync(exe,args,{cwd:temp,encoding:'utf8',env:{...process.env,UNONE_LUAU_ANALYZER:analyzer},maxBuffer:64*1024*1024,windowsHide:true});const rec={sequence:++seq,exe,args,elapsed_ms:performance.now()-started,status:r.status,error:r.error?String(r.error):null,stdout:r.stdout,stderr:r.stderr};fs.writeFileSync(path.join(temp,name+'.raw.json'),JSON.stringify(rec,null,2));fs.appendFileSync(path.join(temp,'replay-ledger.jsonl'),JSON.stringify(rec)+'\n');if(r.status!==0||r.error)throw Error(name+' failed: '+r.stderr);return rec;}
run('strict',binary,['--sdk',sdk,'--project',temp,'--json','check','--types']);run('geometry',binary,['--sdk',sdk,'--project',temp,'--json','run','--frames','2']);const validation=run('external-json-verifier',process.execPath,[path.join(root,'verify-json.mjs'),path.join(temp,'geometry.raw.json')]);
for(const [name,bodies,queries]of [['small',16,4],['large',4096,128]])run('benchmark-'+name,process.execPath,['--import',pathToFileURL(path.join(root,'trace-child-processes.mjs')).href,path.join(sdk,'tools/benchmark-spatial.mjs'),'--sdk',sdk,'--bodies',String(bodies),'--queries',String(queries),'--warmup','3','--samples','9','--output',path.join(temp,'benchmark-'+name+'.json'),'--analyzer',analyzer]);
console.log(JSON.stringify({temp,geometryVerification:JSON.parse(validation.stdout),note:'Later informed replay. Evidence directory was only read; all replay and benchmark writes are in newly created OS-temp directories.'},null,2));
